import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:cached_network_image/cached_network_image.dart';
import '../../features/player/player_provider.dart';

class MiniPlayer extends ConsumerWidget { const MiniPlayer({super.key}); @override Widget build(BuildContext context, WidgetRef ref){ final p=ref.watch(playerProvider); final s=p.current; if(s==null) return const SizedBox(); return GestureDetector(onTap:()=>context.push('/player'), child: Container(height:64, color: const Color(0xFF1A1A1A), padding: const EdgeInsets.symmetric(horizontal:8), child: Row(children:[ClipRRect(borderRadius: BorderRadius.circular(4), child: s['thumbnail']!=null ? CachedNetworkImage(imageUrl:s['thumbnail'], width:48, height:48, fit:BoxFit.cover) : Container(color: const Color(0xFF222), width:48, height:48, child: const Icon(Icons.music_note, color:Colors.white))), const SizedBox(width:10), Expanded(child: Column(crossAxisAlignment:CrossAxisAlignment.start, mainAxisAlignment:MainAxisAlignment.center, children:[Text(s['title']??'', maxLines:1, overflow:TextOverflow.ellipsis, style:const TextStyle(color:Colors.white, fontSize:13, fontWeight:FontWeight.w600)), Text(s['artist']??s['subtitle']??'', maxLines:1, overflow:TextOverflow.ellipsis, style:const TextStyle(color:Colors.grey, fontSize:11))])), IconButton(icon: Icon(p.playing?Icons.pause:Icons.play_arrow, color:Colors.white), onPressed:()=>ref.read(playerProvider.notifier).togglePlay()), IconButton(icon: const Icon(Icons.skip_next, color:Colors.white), onPressed:()=>ref.read(playerProvider.notifier).next())])));}}
